using UnityEngine;
namespace LWS.TruckSports {
// Actual-body events drive pooled River Modeler art/NWH emitters, without changing water or vehicles.
public sealed class SportsWaterInteraction:MonoBehaviour {
 public SportsEventSession session;public SportsMotionReplay replay;public LWS.TruckDockDiving.DockReplay dockReplay;public Transform surface;public Bounds waterBounds;public Rigidbody[] bodies;public ParticleSystem[] spray;public LineRenderer[] ripples;public AudioSource[] audio;public AudioLowPassFilter[] filters;public float WaterHeight=>surface.position.y;public int Entries{get;private set;}public int Wakes{get;private set;}
 struct Event{public float time,power;public Vector3 point;public bool entry,emergence;}readonly Event[] history=new Event[2048];int start,count,pool,ring;Bounds[] local;bool[] wet;float[] next;float priorCursor=-1,lastRecordTime=-1;bool wasReplay;readonly float[] ringBorn=new float[48],ringPower=new float[48];
 void Awake(){local=new Bounds[bodies.Length];wet=new bool[bodies.Length];next=new float[bodies.Length];for(int i=0;i<bodies.Length;i++){bool first=true;foreach(var c in bodies[i].GetComponentsInChildren<Collider>(true)){if(c.isTrigger||c.attachedRigidbody!=bodies[i])continue;var b=c.bounds;for(int k=0;k<8;k++){var p=bodies[i].transform.InverseTransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((k&1)==0?-1:1,(k&2)==0?-1:1,(k&4)==0?-1:1)));if(first){local[i]=new Bounds(p,Vector3.zero);first=false;}else local[i].Encapsulate(p);}}}for(int i=0;i<ripples.Length;i++)ripples[i].enabled=false;}
 void LateUpdate(){bool playback=replay!=null?replay.Playing:dockReplay!=null&&dockReplay.Playing;if(playback){float cursor=replay!=null?replay.Cursor:dockReplay.Clock;if(!wasReplay||cursor<priorCursor){ClearFx();priorCursor=cursor-1.2f;}int emitted=0;for(int k=0;k<count&&emitted<24;k++){var e=history[(start+k)%history.Length];if(e.time>priorCursor&&e.time<=cursor&&cursor-e.time<1.3f){Emit(e,false);emitted++;}}priorCursor=cursor;}else if(session.Live){for(int i=0;i<bodies.Length;i++){var b=bodies[i];if(b==null||!b.gameObject.activeInHierarchy||b.isKinematic){wet[i]=false;continue;}Vector3 p=b.worldCenterOfMass;float y=WaterHeight;bool inside=p.x>=waterBounds.min.x&&p.x<=waterBounds.max.x&&p.z>=waterBounds.min.z&&p.z<=waterBounds.max.z;float bottom=float.MaxValue,top=float.MinValue;var bounds=local[i];for(int k=0;k<8;k++){float h=b.transform.TransformPoint(bounds.center+Vector3.Scale(bounds.extents,new Vector3((k&1)==0?-1:1,(k&2)==0?-1:1,(k&4)==0?-1:1))).y;bottom=Mathf.Min(bottom,h);top=Mathf.Max(top,h);}bool now=inside&&bottom<y+.02f;bool entry=now&&!wet[i],emergence=!now&&wet[i]&&inside;float speed=b.GetPointVelocity(new Vector3(p.x,y,p.z)).magnitude;if((entry||emergence||now&&top>y-.5f&&speed>.35f)&&Time.time>=next[i]&&bottom>y-10){var e=new Event{time=replay!=null?replay.Duration:dockReplay!=null?dockReplay.Duration:Time.time,point=new Vector3(p.x,y+.035f,p.z),power=Mathf.Clamp(entry?Mathf.Abs(b.linearVelocity.y)+speed*.2f:speed*.2f,.3f,12),entry=entry,emergence=emergence};if(replay!=null||dockReplay!=null){if(e.time<lastRecordTime){count=start=0;}lastRecordTime=e.time;int at;if(count==history.Length){at=start;start=(start+1)%history.Length;}else at=(start+count++)%history.Length;history[at]=e;}Emit(e,true);next[i]=Time.time+.18f;if(entry)Entries++;else Wakes++;}wet[i]=now;}}else if(!session.Running){count=start=0;System.Array.Clear(wet,0,wet.Length);ClearFx();}wasReplay=playback;for(int i=0;i<ripples.Length;i++){var line=ripples[i];if(!line.enabled)continue;float age=Time.time-ringBorn[i];if(age>1.4f){line.enabled=false;continue;}float radius=.3f+age*(.8f+ringPower[i]*.18f);line.transform.localScale=new Vector3(radius,1,radius);float alpha=(1-age/1.4f)*.48f;line.startColor=line.endColor=new Color(.8f,.94f,1,alpha);}}
 void Emit(Event e,bool sound){int at=ring++%ripples.Length;var line=ripples[at];line.transform.position=e.point;ringBorn[at]=Time.time;ringPower[at]=e.power;line.enabled=true;var p=spray[pool++%spray.Length];p.transform.position=e.point+(e.emergence?Vector3.up*.8f:Vector3.zero);p.Emit(new ParticleSystem.EmitParams{velocity=e.emergence?Vector3.down*.25f:Vector3.up*Mathf.Clamp(e.power*.45f,.3f,6),startSize=Mathf.Clamp(e.power*.12f,.12f,1.2f)},Mathf.Clamp(Mathf.RoundToInt(e.power*(e.entry?5:1)),1,45));if(sound&&e.entry&&audio.Length>0){var a=audio[pool%audio.Length];a.transform.position=e.point;Camera nearest=null;float distance=float.MaxValue;foreach(var c in session.cameras)if(c!=null&&c.enabled){float d=Vector3.Distance(c.transform.position,e.point);if(d<distance){distance=d;nearest=c;}}a.volume=session.settings.sfx*Mathf.Clamp(e.power*.025f,.02f,.25f)*(nearest!=null?Mathf.Clamp01(1-distance/110):0);a.panStereo=nearest!=null?Vector3.Dot(nearest.transform.right,(e.point-nearest.transform.position).normalized)*.35f:0;var filter=filters[pool%audio.Length];filter.cutoffFrequency=nearest!=null&&nearest.TryGetComponent<LWS.TruckBogSnorkelling.BogCameraEffects>(out var effect)&&effect.Evaluate(nearest)?850:22000;a.pitch=Mathf.Lerp(1.2f,.65f,e.power/12);a.Play();}}
 void ClearFx(){foreach(var p in spray)if(p!=null)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);foreach(var r in ripples)if(r!=null)r.enabled=false;foreach(var a in audio)if(a!=null)a.Stop();}void OnDisable(){ClearFx();}
}}
